7	/* This is a stress test for the allocator, using multiple threads and
8	   transferring objects between threads. It tries to reflect real-world workloads:
9	   - allocation size is distributed linearly in powers of two
10	   - with some fraction extra large (and some very large)
11	   - the allocations are initialized and read again at free
12	   - pointers transfer between threads
13	   - threads are terminated and recreated with some objects surviving in between
14	   - uses deterministic "randomness", but execution can still depend on
15	     (random) thread scheduling. Do not use this test as a benchmark!
16	*/
17	
18	#include <stdio.h>
19	#include <stdlib.h>
20	#include <stdint.h>
21	#include <stdbool.h>
22	#include <string.h>
23	#include <assert.h>
24	
25	#include <mimalloc.h>
26	#include <mimalloc-stats.h>
27	
28	// #define MI_GUARDED         1
29	// #define USE_STD_MALLOC     1
30	
31	// #define MI_USE_HEAPS        1
32	// #define ALLOW_LARGE         1
33	// #define TEST_STRESS_SUBPROCS   1
34	// #define TEST_LEAK              1
35	
36	#define TEST_STRESS            1
37	
38	#ifndef NTHREADS
39	#define NTHREADS               32
40	#endif
41	
42	// > mimalloc-test-stress [THREADS] [SCALE] [ITER]
43	//
44	// argument defaults
45	#if defined(MI_TSAN) && MI_TEST_LIGHT         // with thread-sanitizer reduce the threads to test within the azure pipeline limits
46	static int THREADS = NTHREADS/4;
47	static int SCALE   = 10;
48	static int ITER    = 100;
49	#elif defined(MI_TSAN)          // with thread-sanitizer reduce the threads to test within the azure pipeline limits
50	static int THREADS = NTHREADS/4;
51	static int SCALE   = 25;
52	static int ITER    = 500;
53	#elif defined(MI_UBSAN)       // with undefined behavious sanitizer reduce parameters to stay within the azure pipeline limits
54	static int THREADS = NTHREADS/4;
55	static int SCALE   = 25;
56	static int ITER    = 20;
57	#elif defined(MI_GUARDED)     // with debug guard pages reduce parameters to stay within the azure pipeline limits
58	static int THREADS = NTHREADS/4;
59	static int SCALE   = 25;
60	static int ITER    = 10;
61	#elif MI_DEBUG && MI_TEST_LIGHT
62	static int THREADS = NTHREADS/4;
63	static int SCALE   = 25;
64	static int ITER    = 10;
65	#elif MI_DEBUG
66	static int THREADS = NTHREADS;
67	static int SCALE   = 25;
68	static int ITER    = 25;
69	#else
70	static int THREADS = NTHREADS;      // more repeatable if THREADS <= #processors
71	static int SCALE   = 50;            // scaling factor
72	static int ITER    = 50;            // N full iterations destructing and re-creating all threads
73	#endif
74	
75	#ifndef ALLOW_LARGE
76	#define ALLOW_LARGE  false
77	#endif
78	
79	
80	static bool   allow_large_objects = ALLOW_LARGE;    // allow very large objects? (set to `true` if SCALE>100)
81	
82	static size_t use_one_size = 0;               // use single object size of `N * sizeof(uintptr_t)`?
83	
84	static bool   main_participates = false;       // main thread participates as a worker too
85	
86	#ifdef USE_STD_MALLOC
87	
88	#define custom_calloc(n,s)    calloc(n,s)
89	#define custom_realloc(p,s)   realloc(p,s)
90	#define custom_free(p)        free(p)
91	
92	#else
93	
94	#ifdef MI_USE_HEAPS
95	#if TEST_STRESS_SUBPROCS
96	#error "cannot test rolling heaps with multiple subprocesses (for now)"
97	#endif
98	static mi_heap_t* current_heap;
99	#define custom_calloc(n,s)    mi_heap_calloc(current_heap,n,s)
100	#define custom_realloc(p,s)   mi_heap_realloc(current_heap,p,s)
101	#define custom_free(p)        mi_free(p)
102	#else
103	#define custom_calloc(n,s)    mi_calloc(n,s)
104	#define custom_realloc(p,s)   mi_realloc(p,s)
105	#define custom_free(p)        mi_free(p)
106	#endif
107	
108	#ifndef NDEBUG
109	#define xMI_HEAP_WALK             // walk the theap objects?
110	#endif
111	
112	#endif
113	
114	// transfer pointer between threads
115	#define TRANSFERS     (1000)
116	// static volatile void* transfer[TRANSFERS];
117	
118	
119	#if (UINTPTR_MAX != UINT32_MAX)
120	const uintptr_t cookie = 0xbf58476d1ce4e5b9UL;
121	#else
122	const uintptr_t cookie = 0x1ce4e5b9UL;
123	#endif
124	
125	static void* atomic_exchange_ptr(volatile void** p, void* newval);
126	
127	typedef uintptr_t* random_t;
128	
129	static uintptr_t pick(random_t r) {
130	  uintptr_t x = *r;
131	#if (UINTPTR_MAX > UINT32_MAX)
132	  // by Sebastiano Vigna, see: <http://xoshiro.di.unimi.it/splitmix64.c>
133	  x ^= x >> 30;
134	  x *= 0xbf58476d1ce4e5b9UL;
135	  x ^= x >> 27;
136	  x *= 0x94d049bb133111ebUL;
137	  x ^= x >> 31;
138	#else
139	  // by Chris Wellons, see: <https://nullprogram.com/blog/2018/07/31/>
140	  x ^= x >> 16;
141	  x *= 0x7feb352dUL;
142	  x ^= x >> 15;
143	  x *= 0x846ca68bUL;
144	  x ^= x >> 16;
145	#endif
146	  *r = x;
147	  return x;
148	}
149	
150	static bool chance(size_t perc, random_t r) {
151	  return (pick(r) % 100 <= perc);
152	}
153	
154	static void* alloc_items(size_t items, random_t r) {
155	  if (chance(1, r)) {
156	    if (chance(1, r) && allow_large_objects) items *= 10000;       // 0.01% giant
157	    else if (chance(10, r) && allow_large_objects) items *= 1000;  // 0.1% huge
158	    else items *= 100;                                             // 1% large objects;
159	  }
160	  if (items>=32 && items<=40) items*=2;              // pthreads uses 320b allocations (this shows that more clearly in the stats)
161	  if (use_one_size > 0) items = (use_one_size / sizeof(uintptr_t));
162	  if (items==0) items = 1;
163	  uintptr_t* p = (uintptr_t*)custom_calloc(items,sizeof(uintptr_t));
164	  if (p != NULL) {
165	    for (uintptr_t i = 0; i < items; i++) {
166	      assert(p[i] == 0);
167	      p[i] = (items - i) ^ cookie;
168	    }
169	  }
170	  return p;
171	}
172	
173	static void free_items(void* p) {
174	  if (p != NULL) {
175	    uintptr_t* q = (uintptr_t*)p;
176	    uintptr_t items = (q[0] ^ cookie);
177	    for (uintptr_t i = 0; i < items; i++) {
178	      if ((q[i] ^ cookie) != items - i) {
179	        fprintf(stderr, "memory corruption at block %p at %zu\n", p, i);
180	        abort();
181	      }
182	    }
183	  }
184	  custom_free(p);
185	}
186	
187	#ifdef MI_HEAP_WALK
188	static bool visit_blocks(const mi_theap_t* theap, const mi_theap_area_t* area, void* block, size_t block_size, void* arg) {
189	  (void)(theap); (void)(area);
190	  size_t* total = (size_t*)arg;
191	  if (block != NULL) {
192	    *total += block_size;
193	  }
194	  return true;
195	}
196	#endif
197	
198	static void stress(intptr_t tid, void* vtransfers) {
199	  #ifndef USE_STD_MALLOC
200	  // printf("test stress thread: subproc: %p, tid: %zi\n", mi_subproc_current()._mi_subproc_id, tid);
201	  #endif
202	  volatile void** transfers = (volatile void**)vtransfers;
203	  //bench_start_thread();
204	  uintptr_t r = ((tid + 1) * 43); // rand();
205	  const size_t max_item_shift = 5; // 128
206	  const size_t max_item_retained_shift = max_item_shift + 2;
207	  size_t allocs = 100 * ((size_t)SCALE) * (tid % 8 + 1); // some threads do more
208	  size_t retain = allocs / 2;
209	  void** data = NULL;
210	  size_t data_size = 0;
211	  size_t data_top = 0;
212	  void** retained = (void**)custom_calloc(retain,sizeof(void*));
213	  size_t retain_top = 0;
214	
215	  while (allocs > 0 || retain > 0) {
216	    if (retain == 0 || (chance(50, &r) && allocs > 0)) {
217	      // 50%+ alloc
218	      allocs--;
219	      if (data_top >= data_size) {
220	        data_size += 100000;
221	        data = (void**)custom_realloc(data, data_size * sizeof(void*));
222	      }
223	      data[data_top++] = alloc_items(1ULL << (pick(&r) % max_item_shift), &r);
224	    }
225	    else {
226	      // 25% retain
227	      retained[retain_top++] = alloc_items( 1ULL << (pick(&r) % max_item_retained_shift), &r);
228	      retain--;
229	    }
230	    if (chance(66, &r) && data_top > 0) {
231	      // 66% free previous alloc
232	      size_t idx = pick(&r) % data_top;
233	      free_items(data[idx]);
234	      data[idx] = NULL;
235	    }
236	    if (chance(25, &r) && data_top > 0) {
237	      // 25% exchange a local pointer with the (shared) transfer buffer.
238	      size_t data_idx = pick(&r) % data_top;
239	      size_t transfer_idx = pick(&r) % TRANSFERS;
240	      void* p = data[data_idx];
241	      void* q = atomic_exchange_ptr(&transfers[transfer_idx], p);
242	      data[data_idx] = q;
243	    }
244	  }
245	
246	  #ifdef MI_HEAP_WALK
247	  // walk the theap
248	  size_t total = 0;
249	  mi_theap_visit_blocks(mi_theap_get_default(), true, visit_blocks, &total);
250	  #endif
251	
252	  // free everything that is left
253	  for (size_t i = 0; i < retain_top; i++) {
254	    free_items(retained[i]);
255	  }
256	  for (size_t i = 0; i < data_top; i++) {
257	    free_items(data[i]);
258	  }
259	  custom_free(retained);
260	  custom_free(data);
261	  //bench_end_thread();
262	}
