291	    #endif
292	
293	    run_os_threads(subproc, THREADS, &stress, (void**)transfers);
294	
295	    #if !defined(NDEBUG) && !defined(USE_STD_MALLOC)
296	    // switch between arena and OS allocation for testing
297	    // mi_option_set_enabled(mi_option_disallow_arena_alloc, (n%2)==1);
298	    #endif
299	    #if defined(MI_HEAP_WALK) && defined(MI_USE_HEAPS)
300	    size_t total = 0;
301	    // mi_abandoned_visit_blocks(mi_subproc_main(), -1, true, visit_blocks, &total);
302	    mi_heap_visit_blocks(heap, true, visit_blocks, &total);
303	    #endif
304	
305	    for (int i = 0; i < TRANSFERS; i++) {
306	      if (chance(50, &r) || n + 1 == ITER) { // free all on last run, otherwise free half of the transfers
307	        void* p = atomic_exchange_ptr(&transfers[i], NULL);
308	        free_items(p);
309	      }
310	    }
311	
312	    #if !defined(NDEBUG) || defined(MI_TSAN)
313	    if ((n + 1) % 10 == 0) {
314	      printf("- iterations left: %3d\n", ITER - (n + 1));
315	      #ifndef USE_STD_MALLOC
316	      mi_debug_show_arenas();
317	      #endif
318	      //mi_collect(true);
319	      //mi_debug_show_arenas();
320	    }
321	    #endif
322	  }
323	
324	  #ifndef USE_STD_MALLOC
325	  #ifdef MI_USE_HEAPS
326	  mi_subproc_heap_stats_print_out(mi_subproc_current(),NULL,NULL);
327	  #else
328	  mi_stats_print(NULL);
329	  #endif
330	  #endif
331	
332	  // clean up  (a bit too early in order to test if the final `free_items` still works correctly)
333	  #ifdef MI_USE_HEAPS
334	  for (int i = 0; i < MI_USE_HEAPS; i++) {
335	    mi_heap_delete(prev_heaps[i]); prev_heaps[i] = NULL;
336	  }
337	  mi_heap_delete(current_heap); current_heap = NULL;
338	  #endif
339	
340	  for (int i = 0; i < TRANSFERS; i++) {
341	    void* p = atomic_exchange_ptr(&transfers[i], NULL);
342	    if (p != NULL) {
343	      free_items(p);
344	    }
345	  }
346	}
