477	
478	typedef struct callback_s {
479	  thread_entry_fun_t* fun;
480	  intptr_t tid;
481	  void*    arg;
482	  mi_subproc_id_t subproc;
483	} callback_t;
484	
485	static void* thread_entry(void* param) {
486	  callback_t* cb = (callback_t*)param;
487	  #ifndef USE_STD_MALLOC
488	  if (cb->subproc._mi_subproc_id != NULL) {
489	    mi_subproc_add_current_thread(cb->subproc);
490	  }
491	  #endif
492	  cb->fun(cb->tid,cb->arg);
493	  return NULL;
494	}
495	
496	
497	#ifdef _WIN32
498	
499	#include <windows.h>
500	
501	static DWORD WINAPI win_thread_entry(LPVOID param) {
502	  thread_entry(param);
503	  return 0;
504	}
505	
506	static void run_os_threads(mi_subproc_id_t subproc, size_t nthreads, thread_entry_fun_t* fun, void* arg) {
507	  DWORD* tids = (DWORD*)custom_calloc(nthreads,sizeof(DWORD));
508	  HANDLE* thandles = (HANDLE*)custom_calloc(nthreads,sizeof(HANDLE));
509	  callback_t* callbacks = (callback_t*)custom_calloc(nthreads,sizeof(callback_t));
510	  thandles[0] = GetCurrentThread(); // avoid lint warning
511	  const size_t start = (main_participates ? 1 : 0);
512	  for (size_t i = start; i < nthreads; i++) {
513	    callbacks[i].fun = fun;
514	    callbacks[i].tid = i;
515	    callbacks[i].arg = arg;
516	    callbacks[i].subproc = subproc;
517	    thandles[i] = CreateThread(0, 8*1024L, &win_thread_entry, (void*)&callbacks[i], 0, &tids[i]);
518	  }
519	  if (main_participates) {
520	    fun(0,arg); // run the main thread as well
521	  }
522	  for (size_t i = start; i < nthreads; i++) {
523	    WaitForSingleObject(thandles[i], INFINITE);
